INSERT INTO `archive_classifications` VALUES (2971, '68d92725-075f-4a66-9fef-204e28a2149d', 2966, '5', '900.1.13.5', 'Pinjam Dan Obligasi Daerah', 'antara lain: Fasilitasi pelaksanaan kebijakan pinjaman dan hibah kepada pemerintah daerah dan/atau badan usaha milik daerah, Fasilitasi pelaksanaan kebijakan obligasi daerah, Fasilitasi pelaksanaan kebijakan dana bergulir yang bersumber dari APBN, Bimbingan teknis obligasi daerah, dana bergulir serta penyertaan modal daerah, Penyiapan pelaksanaan monitoring dan evaluasi pinjaman dan hibah, obligasi daerah, dan dana bergulir, dan penyertaan modal daerah', 4, 1, '2026-07-28 04:20:09', '2026-07-28 04:20:09');
